CREATE TABLE "public"."enrollments" (
  "id"                bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "user_id"           uuid,
  "course_id"         bigint,
  "current_lesson_id" bigint,
  "current_step_id"   bigint,
  "is_completed"      boolean                  DEFAULT false,
  "last_accessed_at"  timestamp with time zone DEFAULT now(),
  CONSTRAINT "enrollments_course_id_fkey" FOREIGN KEY (course_id) REFERENCES public.courses(id) ON DELETE CASCADE,
  CONSTRAINT "enrollments_pkey" PRIMARY KEY (id),
  CONSTRAINT "enrollments_user_id_course_id_key" UNIQUE (user_id, course_id),
  CONSTRAINT "enrollments_current_lesson_id_fkey" FOREIGN KEY (current_lesson_id) REFERENCES public.lessons(id),
  CONSTRAINT "enrollments_user_id_fkey" FOREIGN KEY (user_id) REFERENCES public.profiles(id),
  CONSTRAINT "enrollments_current_step_id_fkey" FOREIGN KEY (current_step_id) REFERENCES public.steps(id) ON DELETE SET NULL
);

REVOKE ALL ON SEQUENCE "public"."enrollments_id_seq" FROM "anon";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."enrollments_id_seq" TO "anon";

REVOKE ALL ON SEQUENCE "public"."enrollments_id_seq" FROM "authenticated";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."enrollments_id_seq" TO "authenticated";

REVOKE ALL ON SEQUENCE "public"."enrollments_id_seq" FROM "postgres";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."enrollments_id_seq" TO "postgres";

REVOKE ALL ON SEQUENCE "public"."enrollments_id_seq" FROM "service_role";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."enrollments_id_seq" TO "service_role";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."enrollments" TO "anon", "authenticated";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."enrollments" TO "service_role";

REVOKE ALL ON TABLE "public"."enrollments" FROM "postgres";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."enrollments" TO "postgres";
